package com.opspilot.incident.api;
import com.opspilot.incident.infrastructure.persistence.IncidentFacade; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.UUID; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/api/v1/incidents") public class IncidentController {private final IncidentFacade facade; public IncidentController(IncidentFacade f){facade=f;}@GetMapping public PageResponse<IncidentResponse> list(@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size){return facade.incidents(page,size);}@GetMapping("/{id}")public IncidentResponse get(@PathVariable UUID id){return facade.incident(id);}@PostMapping("/{id}/acknowledge")public IncidentResponse ack(@PathVariable UUID id){return facade.acknowledge(id);}@PostMapping("/{id}/start-investigation")public IncidentResponse investigate(@PathVariable UUID id){return facade.investigate(id);}@PostMapping("/{id}/resolve")public IncidentResponse resolve(@PathVariable UUID id,@Valid @RequestBody ResolveIncidentRequest r){return facade.resolve(id,r.summary());}}
